package recoveryexport

// Fixed PostgreSQL16 definitions of db/binding_postgres.sql.
var bindingConstraints = map[identityConstraintKey]identityConstraintSpec{
	{"binding_operation", "binding_operation_action_check"}:                  {"c", "CHECK ((action = ANY (ARRAY['bind'::text, 'relocate'::text, 'rebind'::text, 'source-register'::text, 'source-rebind'::text, 'source-disable'::text])))"},
	{"binding_operation", "binding_operation_check"}:                         {"c", "CHECK ((to_revision = (from_revision + 1)))"},
	{"binding_operation", "binding_operation_from_revision_check"}:           {"c", "CHECK ((from_revision >= 0))"},
	{"binding_operation", "binding_operation_generation_check"}:              {"c", "CHECK ((generation ~ '^[0-9a-f]{32}$'::text))"},
	{"binding_operation", "binding_operation_manifest_sha256_check"}:         {"c", "CHECK ((manifest_sha256 ~ '^[0-9a-f]{64}$'::text))"},
	{"binding_operation", "binding_operation_operation_id_check"}:            {"c", "CHECK ((operation_id ~ '^bind_[0-9a-f]{32}$'::text))"},
	{"binding_operation", "binding_operation_pkey"}:                          {"p", "PRIMARY KEY (operation_id)"},
	{"binding_operation", "binding_operation_plan_sha256_check"}:             {"c", "CHECK ((plan_sha256 ~ '^[0-9a-f]{64}$'::text))"},
	{"binding_operation", "binding_operation_request_sha256_check"}:          {"c", "CHECK ((request_sha256 ~ '^[0-9a-f]{64}$'::text))"},
	{"binding_operation", "binding_operation_root_id_fkey"}:                  {"f", "FOREIGN KEY (root_id) REFERENCES storage_root_identity(root_id)"},
	{"binding_operation", "binding_operation_root_id_to_revision_key"}:       {"u", "UNIQUE (root_id, to_revision)"},
	{"configured_source", "configured_source_capture_enabled_check"}:         {"c", "CHECK ((capture_enabled = false))"},
	{"configured_source", "configured_source_pkey"}:                          {"p", "PRIMARY KEY (source_id)"},
	{"configured_source", "configured_source_repository_id_fkey"}:            {"f", "FOREIGN KEY (repository_id) REFERENCES repository_identity(repository_id)"},
	{"configured_source", "configured_source_slot_check"}:                    {"c", "CHECK (((slot >= 1) AND (slot <= 64)))"},
	{"configured_source", "configured_source_slot_key"}:                      {"u", "UNIQUE (slot)"},
	{"configured_source", "configured_source_source_id_check"}:               {"c", "CHECK ((source_id ~ '^source_[0-9a-f]{32}$'::text))"},
	{"root_binding_head", "root_binding_head_capability_check"}:              {"c", "CHECK ((capability = 'physical-binding-v1/recovery-only'::text))"},
	{"root_binding_head", "root_binding_head_pkey"}:                          {"p", "PRIMARY KEY (root_id)"},
	{"root_binding_head", "root_binding_head_root_id_fkey"}:                  {"f", "FOREIGN KEY (root_id) REFERENCES storage_root_identity(root_id)"},
	{"root_binding_head", "root_binding_head_root_id_revision_fkey"}:         {"f", "FOREIGN KEY (root_id, revision) REFERENCES root_binding_revision(root_id, revision)"},
	{"root_binding_revision", "root_binding_revision_evidence_check"}:        {"c", "CHECK (((octet_length(evidence) >= 2) AND (octet_length(evidence) <= 4096)))"},
	{"root_binding_revision", "root_binding_revision_incarnation_check"}:     {"c", "CHECK ((incarnation ~ '^incarnation_[0-9a-f]{32}$'::text))"},
	{"root_binding_revision", "root_binding_revision_installation_id_check"}: {"c", "CHECK ((installation_id ~ '^install_[0-9a-f]{32}$'::text))"},
	{"root_binding_revision", "root_binding_revision_operation_id_fkey"}:     {"f", "FOREIGN KEY (operation_id) REFERENCES binding_operation(operation_id)"},
	{"root_binding_revision", "root_binding_revision_operation_id_key"}:      {"u", "UNIQUE (operation_id)"},
	{"root_binding_revision", "root_binding_revision_path_base64_check"}:     {"c", "CHECK (((octet_length(path_base64) >= 4) AND (octet_length(path_base64) <= 4096)))"},
	{"root_binding_revision", "root_binding_revision_pkey"}:                  {"p", "PRIMARY KEY (root_id, revision)"},
	{"root_binding_revision", "root_binding_revision_revision_check"}:        {"c", "CHECK ((revision > 0))"},
	{"root_binding_revision", "root_binding_revision_root_id_fkey"}:          {"f", "FOREIGN KEY (root_id) REFERENCES storage_root_identity(root_id)"},
	{"source_binding_head", "source_binding_head_pkey"}:                      {"p", "PRIMARY KEY (source_id)"},
	{"source_binding_head", "source_binding_head_source_id_fkey"}:            {"f", "FOREIGN KEY (source_id) REFERENCES configured_source(source_id)"},
	{"source_binding_head", "source_binding_head_source_id_revision_fkey"}:   {"f", "FOREIGN KEY (source_id, revision) REFERENCES source_binding_revision(source_id, revision)"},
	{"source_binding_revision", "source_binding_revision_continuity_check"}:  {"c", "CHECK ((continuity = ANY (ARRAY['new'::text, 'same-object'::text, 'changed'::text, 'disabled'::text])))"},
	{"source_binding_revision", "source_binding_revision_evidence_check"}:    {"c", "CHECK (((octet_length(evidence) >= 2) AND (octet_length(evidence) <= 4096)))"},
	{"source_binding_revision", "source_binding_revision_operation_id_fkey"}: {"f", "FOREIGN KEY (operation_id) REFERENCES binding_operation(operation_id)"},
	{"source_binding_revision", "source_binding_revision_operation_id_key"}:  {"u", "UNIQUE (operation_id)"},
	{"source_binding_revision", "source_binding_revision_path_base64_check"}: {"c", "CHECK (((octet_length(path_base64) >= 4) AND (octet_length(path_base64) <= 4096)))"},
	{"source_binding_revision", "source_binding_revision_pkey"}:              {"p", "PRIMARY KEY (source_id, revision)"},
	{"source_binding_revision", "source_binding_revision_revision_check"}:    {"c", "CHECK ((revision > 0))"},
	{"source_binding_revision", "source_binding_revision_source_id_fkey"}:    {"f", "FOREIGN KEY (source_id) REFERENCES configured_source(source_id)"},
}
